// @call = applyEndpoints
const applyEndpoints = ({ config = {}, endpoints = [], ...rest }) => {
  const tailnetIPRanges = ["100.64.0.0/10", "fd7a:115c:a1e0::/48"];
  const endpoint = $options?._req?.query?.endpoint ?? "";

  // endpoint id generated by:
  // $ openssl rand -hex 16
  const endpointIDs = endpoint.split("_");
  if (endpointIDs.length === 0) return { config, endpoints: [], ...rest };

  const availableEndpoints = (endpoints ?? []).filter((ep) =>
    (endpointIDs ?? []).some((eid) => ep.properties?.endpoint?.id == eid),
  );

  if (availableEndpoints.length == 0) {
    // no endpoint available , so exclude tailnet ip range to tun configure.
    const tunInbound = findTun(config);
    if (tunInbound) {
      tunInbound.route_exclude_address = [
        ...(tunInbound.route_exclude_address ?? []),
        ...tailnetIPRanges,
      ];
    }

    return { config, endpoints, ...rest };
  }

  // tailscale endpoints
  const tailscaleEndpoints = availableEndpoints
    .filter((ep) => ep.type === "tailscale")
    .map((tsep) => {
      config.route = {
        ...(config.route ?? {}),
        rules: [
          {
            action: "route",
            outbound: tsep.name,
            preferred_by: tsep.name,
          },
          ...(config.route?.rules ?? []),
        ],
      };
      config.dns = {
        ...(config.dns ?? {}),
        servers: [
          ...(config.dns?.servers ?? []),
          {
            type: "tailscale",
            tag: "dns-" + tsep.name,
            endpoint: tsep.name,
            accept_search_domain: true,
          },
        ],
        rules: [
          {
            action: "evaluate",
            preferred_by: "dns-" + tsep.name,
            server: "dns-" + tsep.name,
            tag: "resolve-evaluate-tailscale-" + tsep.name,
          },
          {
            match_response: "resolve-evaluate-tailscale-" + tsep.name,
            ip_accept_any: true,
            action: "respond",
          },
          ...(config.dns?.rules ?? []),
        ],
      };
      return tsep;
    });

  // wireguard endpoints
  const wireguardEndpoints = availableEndpoints
    .filter((ep) => ep.type === "wireguard")
    .map((wgep) => {
      config.route = {
        ...(config.route ?? {}),
        rules: [
          {
            action: "route",
            outbound: wgep.name,
            preferred_by: wgep.name,
          },
          ...(config.route?.rules ?? []),
        ],
      };
      return wgep;
    });

  // openvpn-(client/server) , openconnect not supported

  return {
    config,
    endpoints: [...(tailscaleEndpoints ?? []), ...(wireguardEndpoints ?? [])],
    ...rest,
  };
};
